const COUNTRIES = {
  US: {
    name: "United States",
    fields: [
      { id: "street", label: "Street address", required: true },
      { id: "city", label: "City", required: true },
      {
        id: "state",
        label: "State",
        required: true,
        type: "select",
        options: ["AL","AK","AZ","AR","CA","CO","CT","DE","FL","GA","HI","ID","IL","IN","IA","KS","KY","LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ","NM","NY","NC","ND","OH","OK","OR","PA","RI","SC","SD","TN","TX","UT","VT","VA","WA","WV","WI","WY"],
      },
      {
        id: "postal",
        label: "ZIP code",
        required: true,
        pattern: /^\d{5}(-\d{4})?$/,
        hint: "5 digits, e.g. 94103, or 94103-1234",
      },
    ],
  },
  GB: {
    name: "United Kingdom",
    fields: [
      { id: "street", label: "Street address", required: true },
      { id: "city", label: "Town / City", required: true },
      {
        id: "postal",
        label: "Postcode",
        required: true,
        pattern: /^[A-Za-z]{1,2}\d[A-Za-z\d]?\s?\d[A-Za-z]{2}$/,
        hint: "e.g. SW1A 1AA",
      },
    ],
  },
  NG: {
    name: "Nigeria",
    fields: [
      { id: "street", label: "Street address", required: true },
      { id: "city", label: "City / LGA", required: true },
      {
        id: "state",
        label: "State",
        required: true,
        type: "select",
        options: ["Abia","Adamawa","Akwa Ibom","Anambra","Bauchi","Bayelsa","Benue","Borno","Cross River","Delta","Ebonyi","Edo","Ekiti","Enugu","FCT","Gombe","Imo","Jigawa","Kaduna","Kano","Katsina","Kebbi","Kogi","Kwara","Lagos","Nasarawa","Niger","Ogun","Ondo","Osun","Oyo","Plateau","Rivers","Sokoto","Taraba","Yobe","Zamfara"],
      },
      {
        id: "postal",
        label: "Postal code (optional)",
        required: false,
        pattern: /^\d{6}$/,
        hint: "6 digits, if you have one",
      },
    ],
  },
  OTHER: {
    name: "Other / not listed",
    fields: [
      { id: "street", label: "Street address", required: true },
      { id: "city", label: "City", required: true },
      { id: "region", label: "State / Province / Region", required: false },
      { id: "postal", label: "Postal code", required: false },
    ],
  },
};

function el(tag, attrs = {}, children = []) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === "text") node.textContent = v;
    else node.setAttribute(k, v);
  }
  children.forEach((c) => node.appendChild(c));
  return node;
}

function renderFields(countryCode) {
  const container = document.getElementById("dynamic-fields");
  container.innerHTML = "";
  const country = COUNTRIES[countryCode];

  country.fields.forEach((field) => {
    const wrap = el("div", { class: "field" });
    const labelText = field.required ? field.label : `${field.label} (optional)`;
    wrap.appendChild(el("label", { for: field.id, text: labelText }));

    let input;
    if (field.type === "select") {
      input = el("select", { id: field.id, name: field.id });
      input.appendChild(el("option", { value: "", text: `Select ${field.label.toLowerCase()}` }));
      field.options.forEach((opt) => input.appendChild(el("option", { value: opt, text: opt })));
    } else {
      input = el("input", { type: "text", id: field.id, name: field.id });
    }
    wrap.appendChild(input);

    if (field.hint) {
      wrap.appendChild(el("p", { class: "hint", id: `${field.id}-hint`, text: field.hint }));
      input.setAttribute("aria-describedby", `${field.id}-hint`);
    }
    wrap.appendChild(el("p", { class: "error", id: `${field.id}-error`, role: "alert" }));

    container.appendChild(wrap);
  });
}

function validate(countryCode, formData) {
  const country = COUNTRIES[countryCode];
  const errors = {};

  country.fields.forEach((field) => {
    const value = (formData.get(field.id) || "").trim();

    if (field.required && !value) {
      errors[field.id] = `${field.label} is required.`;
      return;
    }
    if (value && field.pattern && !field.pattern.test(value)) {
      errors[field.id] = `That doesn't look like a valid ${field.label.toLowerCase()}.${field.hint ? " " + field.hint : ""}`;
    }
  });

  return errors;
}

function showErrors(countryCode, errors) {
  const country = COUNTRIES[countryCode];
  country.fields.forEach((field) => {
    const errorEl = document.getElementById(`${field.id}-error`);
    const inputEl = document.getElementById(field.id);
    if (!errorEl || !inputEl) return;

    const message = errors[field.id] || "";
    errorEl.textContent = message;

    const describedBy = [field.hint ? `${field.id}-hint` : "", message ? `${field.id}-error` : ""]
      .filter(Boolean)
      .join(" ");
    if (describedBy) inputEl.setAttribute("aria-describedby", describedBy);
    inputEl.setAttribute("aria-invalid", message ? "true" : "false");
  });
}

function init() {
  const countrySelect = document.getElementById("country");
  Object.entries(COUNTRIES).forEach(([code, c]) => {
    countrySelect.appendChild(el("option", { value: code, text: c.name }));
  });
  countrySelect.value = "US";
  renderFields("US");

  countrySelect.addEventListener("change", () => renderFields(countrySelect.value));

  document.getElementById("address-form").addEventListener("submit", (e) => {
    e.preventDefault();
    const countryCode = countrySelect.value;
    const formData = new FormData(e.target);
    const errors = validate(countryCode, formData);
    showErrors(countryCode, errors);

    const status = document.getElementById("form-status");
    if (Object.keys(errors).length > 0) {
      status.textContent = "Please fix the highlighted fields.";
      const firstErrorId = Object.keys(errors)[0];
      document.getElementById(firstErrorId)?.focus();
    } else {
      status.textContent = "Address saved — looks good!";
    }
  });
}

document.addEventListener("DOMContentLoaded", init);

if (typeof module !== "undefined") {
  module.exports = { COUNTRIES, validate };
}

:root {
  --bg: #f5f7fa;
  --surface: #ffffff;
  --text: #1a2233;
  --muted: #5b6577;
  --accent: #2f6fed;
  --border: #d7dce4;
  --error: #c92a2a;
  --radius: 10px;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #12151c;
    --surface: #1b1f29;
    --text: #e9edf5;
    --muted: #9aa4b8;
    --accent: #5b8dff;
    --border: #2c3242;
    --error: #ff6b6b;
  }
}

* { box-sizing: border-box; }
body { margin: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: var(--bg); color: var(--text); }
.wrap { max-width: 480px; margin: 0 auto; padding: 2.5rem 1.5rem 4rem; }
h1 { margin-bottom: 0.25rem; }
.lede { color: var(--muted); margin-top: 0; line-height: 1.5; }

form {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.field { display: flex; flex-direction: column; gap: 0.35rem; }
label { font-weight: 600; font-size: 0.9rem; }

input, select {
  font: inherit;
  padding: 0.55rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--bg);
  color: var(--text);
}

input[aria-invalid="true"] { border-color: var(--error); }

.hint { margin: 0; font-size: 0.8rem; color: var(--muted); }
.error { margin: 0; font-size: 0.8rem; color: var(--error); min-height: 1em; }

button {
  align-self: flex-start;
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 0.65rem 1.4rem;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
}
button:hover { filter: brightness(1.08); }

#form-status { font-weight: 600; }
